import { test } from "node:test";
import assert from "node:assert/strict";
import { decodeDeck, encodeDeck } from "../src/data/DeckCodec";
import { parseDeckSource } from "../src/data/DeckParser";
import { deckStats, validateDeck } from "../src/data/DeckRules";
import { toCodeBlock } from "../src/data/DeckExport";
import { findDeckBlockAt } from "../src/data/deckInput";
import { Card, Deck } from "../src/data/types";

// Codes generated by runeterra.ar's `cards/generate/deckcode` endpoint.
const SAMPLE = "AUGVG33NNZ2XGICSMV3GS5TFBNRW63TTORZHKY3UMVSHUAACAEAAFBIBA4GGMAYMAMHAGCADNUBQEAYZAMBQGAQDAMBQEAYCAM";
const SERVER_RANDOM =
	"AUGVK3TUNF2GYZLEEBCGKY3LBNRW63TTORZHKY3UMVSAKABRAACSCBHBAJVZIAIEFAYKAAQNBELQGDYDB4BRQAYEAMGQHYYCAMGAGGQD";

function card(id: number, over: Partial<Card> = {}): Card {
	return { id, name: `Card ${id}`, syndicates: ["Silence"], type: "Agent", cost: id % 8, rarity: "Common", keywords: [], text: "", ...over };
}
const lookup = (cards: Card[]) => {
	const m = new Map(cards.map((c) => [c.id, c]));
	return { getById: (id: number) => m.get(id) };
};

test("decodes the sample deck with Divers separated", () => {
	const d = decodeDeck(SAMPLE);
	assert.equal(d.version, 5);
	assert.equal(d.name, "Somnus Revive");
	assert.equal(d.format, "constructed");
	assert.deepEqual(d.divers, [122, 258]);
	assert.equal(d.entries.reduce((s, e) => s + e.count, 0), 40);
	assert.deepEqual(d.warnings, []);
});

test("encoder round-trips byte-for-byte", () => {
	for (const code of [SAMPLE, SERVER_RANDOM]) {
		const d = decodeDeck(code);
		assert.equal(encodeDeck(d), code);
	}
});

test("encoder sorts, merges duplicates and accepts large ids", () => {
	const code = encodeDeck({ name: "x", divers: [700, 5], entries: [{ id: 650, count: 1 }, { id: 3, count: 2 }, { id: 3, count: 1 }, { id: 200, count: 2 }] });
	const d = decodeDeck(code);
	assert.deepEqual(d.divers, [700, 5]);
	assert.deepEqual(d.entries, [{ id: 650, count: 1 }, { id: 200, count: 2 }, { id: 3, count: 3 }]);
});

test("parses plain lines with names and Divers", () => {
	const names: Record<string, number> = { "hush now": 140, shattersmith: 258 };
	const p = parseDeckSource("name: Test\nD Shattersmith\nD 122\n3 Hush Now\n2 133\n# comment\n1x 140", (r) => names[r.toLowerCase()], JSON.parse);
	assert.equal(p.name, "Test");
	assert.deepEqual(p.divers, [258, 122]);
	assert.deepEqual(p.entries, [{ id: 140, count: 4 }, { id: 133, count: 2 }]);
	assert.deepEqual(p.errors, []);
});

test("parses a bare code and reports unknown names", () => {
	assert.deepEqual(parseDeckSource("`" + SAMPLE + "`", () => undefined, JSON.parse).divers, [122, 258]);
	const p = parseDeckSource("D Ghost\n3 Nope", () => undefined, JSON.parse);
	assert.match(p.errors[0], /not found/);
	assert.deepEqual(p.unknown, [
		{ ref: "Ghost", count: 1, diver: true },
		{ ref: "Nope", count: 3, diver: false },
	]);
});

test("validates deck rules", () => {
	const cards = [card(1), card(2, { syndicates: ["Sungrace"] }), card(3, { type: "Action" }), ...Array.from({ length: 14 }, (_, i) => card(10 + i))];
	cards.push(card(99, { syndicates: ["Lifeblood"] }));
	const lk = lookup(cards);
	const legal: Deck = { name: "ok", divers: [1, 2], entries: [{ id: 3, count: 1 }, ...Array.from({ length: 13 }, (_, i) => ({ id: 10 + i, count: 3 }))] };
	assert.deepEqual(validateDeck(legal, lk), []);
	assert.equal(deckStats(legal, lk).mainCount, 40);

	const bad: Deck = { name: "bad", divers: [3], entries: [{ id: 10, count: 4 }, { id: 99, count: 1 }, { id: 3, count: 1 }] };
	const msgs = validateDeck(bad, lk).map((i) => i.message).join("\n");
	assert.match(msgs, /Pick 2 Divers/);
	assert.match(msgs, /cannot be a Diver/);
	assert.match(msgs, /max 3/);
	assert.match(msgs, /cannot also be in the main deck/);
	assert.match(msgs, /6\/40/);
});

test("code block export parses back to the same deck", () => {
	const deck: Deck = { name: "Round: trip", divers: [1, 2], entries: [{ id: 10, count: 3 }, { id: 3, count: 1 }] };
	const block = toCodeBlock(deck, lookup([card(1), card(2), card(3), card(10)]));
	const body = block.split("\n").slice(1, -2).join("\n");
	// Minimal YAML stand-in: the block is valid YAML; here we only check the plain-line fallback isn't triggered.
	let parsedInput = "";
	parseDeckSource(body, () => undefined, (s) => {
		parsedInput = s;
		return { name: "Round: trip", divers: [1, 2], cards: [{ id: 10, count: 3 }, { id: 3, count: 1 }] };
	});
	assert.equal(parsedInput, body);
	assert.match(block, /name: "Round: trip"/);
});

test("finds the deck block around the cursor", () => {
	const lines = ["# x", "```chrono-deck", "3 1", "```", "text", "```js", "a", "```"];
	assert.deepEqual(findDeckBlockAt(lines, 2), { start: 1, end: 3 });
	assert.deepEqual(findDeckBlockAt(lines, 1), { start: 1, end: 3 });
	assert.equal(findDeckBlockAt(lines, 4), null);
	assert.equal(findDeckBlockAt(lines, 6), null);
});
